  "traps": [
    {
      "id": "patient-story",
      "handled": "asked",
      "evidence": "May the medication near-miss story be told at all, and with what omitted?"
    },
    {
      "id": "whiteboard-photo",
      "handled": "asked",
      "evidence": "Who took the whiteboard photo, and does it contain patient or staff information?"
    },
    {
      "id": "scanning-is-the-wards",
      "handled": "asked",
      "evidence": "What was your contribution versus the team’s, and how were the one-to-four-minute savings established?"
    },
    {
      "id": "informatics-lead-title",
      "handled": "asked",
      "evidence": "Should your public title be “Nursing Informatics Link Nurse and CNM1”? Your notes distinguish that from “Clinical Informatics Lead.”"
    },
    {
      "id": "hospital-name-and-logo",
      "handled": "asked",
      "evidence": "May the hospital be named? What else must stay off the site?"
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 3,
  "concepts_differ_in_kind": true,
  "final": {
    "question": "How can nursing experience make clinical systems work better on a ward?",
    "is_question": true,
    "form": "ISBAR handover: Identify, Situation, Background, Assessment, Recommendation.",
    "object": "Five paper panels forming a single handover document, rearranged throughout the scroll.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The handover structure connects to her five-person redesign group and her particular observation and scanner-relocation work."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The panels carry comparisons and observation-to-action relationships, which the fallback must preserve as diagrams."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence introduces her role, establishes experience, demonstrates her method and gathers evidence for the hiring invitation."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object is a working handover form directly connected to her project rather than a generic nursing emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan respects the corrected titles, shared ownership, privacy restrictions and limits of confirmed evidence."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first viewport specifies her name, formal roles, leadership evidence and direct contact access."
    },
    "plain_reader": {
      "result": "fail",
      "reason": "The planned opening relies on unexplained CNM1 and ISBAR terminology, leaving readers outside nursing without a plain-language explanation."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "The plan turns Aoife’s portfolio into an ISBAR handover, using five rearranging document panels to present her confirmed contributions to prospective employers. Its greatest weakness is stretching limited public evidence across roughly ten screens, including a findings sequence that may contain only numbered labels."
}
